[metadata] {"type": "create", "filePath": "/app/output/index.html", "content": "<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <title>StreamWave — Unlimited Films, Series and More</title>
  <style>
    *, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

    :root {
      --bg: #000000;
      --bg-card: #1a1a1a;
      --bg-card-hover: #252525;
      --accent: #E50914;
      --accent-hover: #f40d18;
      --text: #FFFFFF;
      --text-muted: #a0a0a0;
      --border: #333333;
      --max-width: 1200px;
    }

    html { scroll-behavior: smooth; }

    body {
      font-family: 'Segoe UI', -apple-system, BlinkMacSystemFont, Roboto, 'Helvetica Neue', Arial, sans-serif;
      background: var(--bg);
      color: var(--text);
      line-height: 1.5;
      -webkit-font-smoothing: antialiased;
    }

    a { color: var(--text-muted); text-decoration: none; }
    a:hover { text-decoration: underline; }

    /* ===== HEADER ===== */
    .header {
      position: absolute;
      top: 0; left: 0; right: 0;
      z-index: 100;
      display: flex;
      justify-content: space-between;
      align-items: center;
      padding: 20px 48px;
    }
    .logo {
      font-size: 1.75rem;
      font-weight: 800;
      color: var(--accent);
      letter-spacing: -0.5px;
      text-transform: uppercase;
    }
    .header-right {
      display: flex;
      align-items: center;
      gap: 16px;
    }
    .lang-select {
      background: transparent;
      color: var(--text);
      border: 1px solid var(--border);
      padding: 6px 12px;
      border-radius: 4px;
      font-size: 0.875rem;
      cursor: pointer;
    }
    .lang-select option { background: #222; }
    .btn-signin {
      background: var(--accent);
      color: var(--text);
      border: none;
      padding: 8px 20px;
      border-radius: 4px;
      font-size: 0.9rem;
      font-weight: 600;
      cursor: pointer;
      transition: background 0.2s;
    }
    .btn-signin:hover { background: var(--accent-hover); }

    /* ===== HERO ===== */
    .hero {
      position: relative;
      min-height: 85vh;
      display: flex;
      flex-direction: column;
      justify-content: center;
      align-items: center;
      text-align: center;
      padding: 120px 24px 60px;
      overflow: hidden;
    }
    .hero-bg {
      position: absolute;
      inset: 0;
      background:
        linear-gradient(135deg,
          #1a0a0a 0%, #0d0d0d 20%, #0a0a1a 40%,
          #0d0d0d 60%, #1a0a0a 80%, #0d0d0d 100%);
      z-index: 0;
    }
    .hero-bg::before {
      content: '';
      position: absolute;
      inset: 0;
      background:
        radial-gradient(ellipse at 20% 50%, rgba(229,9,20,0.08) 0%, transparent 50%),
        radial-gradient(ellipse at 80% 50%, rgba(229,9,20,0.06) 0%, transparent 50%);
    }
    .hero-bg::after {
      content: '';
      position: absolute;
      inset: 0;
      background: linear-gradient(to bottom, rgba(0,0,0,0.6) 0%, rgba(0,0,0,0.4) 40%, rgba(0,0,0,0.8) 85%, #000 100%);
    }
    .hero-content {
      position: relative;
      z-index: 1;
      max-width: 800px;
    }
    .hero h1 {
      font-size: clamp(2rem, 5.5vw, 3.75rem);
      font-weight: 800;
      line-height: 1.1;
      margin-bottom: 16px;
      letter-spacing: -0.5px;
    }
    .hero-subtitle {
      font-size: clamp(1.1rem, 2.5vw, 1.5rem);
      font-weight: 400;
      margin-bottom: 24px;
      color: var(--text);
    }
    .hero-prompt {
      font-size: clamp(0.95rem, 1.8vw, 1.2rem);
      color: var(--text-muted);
      margin-bottom: 24px;
    }
    .email-form {
      display: flex;
      gap: 8px;
      max-width: 580px;
      margin: 0 auto;
    }
    .email-form input {
      flex: 1;
      padding: 16px 16px;
      background: rgba(22,22,22,0.9);
      border: 1px solid var(--border);
      border-radius: 4px;
      color: var(--text);
      font-size: 1rem;
      outline: none;
      transition: border-color 0.2s;
    }
    .email-form input::placeholder { color: #666; }
    .email-form input:focus { border-color: #666; }
    .btn-cta {
      display: inline-flex;
      align-items: center;
      gap: 6px;
      background: var(--accent);
      color: var(--text);
      border: none;
      padding: 16px 28px;
      border-radius: 4px;
      font-size: 1.1rem;
      font-weight: 700;
      cursor: pointer;
      white-space: nowrap;
      transition: background 0.2s;
    }
    .btn-cta:hover { background: var(--accent-hover); }
    .btn-cta .arrow { font-size: 1.4rem; line-height: 1; }

    /* ===== TRENDING ===== */
    .trending {
      padding: 50px 0 40px;
      position: relative;
    }
    .section-container {
      max-width: var(--max-width);
      margin: 0 auto;
      padding: 0 48px;
    }
    .section-title {
      font-size: clamp(1.3rem, 2.5vw, 1.75rem);
      font-weight: 700;
      margin-bottom: 24px;
    }
    .carousel-wrapper {
      position: relative;
    }
    .carousel-track {
      display: flex;
      gap: 12px;
      overflow-x: auto;
      scroll-behavior: smooth;
      scrollbar-width: none;
      -ms-overflow-style: none;
      padding: 10px 0 20px;
    }
    .carousel-track::-webkit-scrollbar { display: none; }
    .carousel-card {
      flex: 0 0 auto;
      width: 200px;
      position: relative;
      border-radius: 6px;
      overflow: hidden;
      cursor: pointer;
      transition: transform 0.25s;
    }
    .carousel-card:hover { transform: scale(1.05); }
    .card-poster {
      width: 100%;
      height: 280px;
      display: flex;
      align-items: flex-end;
      justify-content: center;
      padding: 16px 12px;
      position: relative;
    }
    .card-rank {
      position: absolute;
      bottom: -20px;
      left: -10px;
      font-size: 8rem;
      font-weight: 900;
      line-height: 1;
      color: rgba(0,0,0,0.5);
      -webkit-text-stroke: 2px rgba(255,255,255,0.2);
      pointer-events: none;
      user-select: none;
    }
    .card-title {
      position: relative;
      z-index: 2;
      font-size: 0.9rem;
      font-weight: 700;
      text-align: center;
      text-shadow: 0 2px 8px rgba(0,0,0,0.8);
    }
    .carousel-btn {
      position: absolute;
      top: 50%;
      transform: translateY(-50%);
      width: 44px;
      height: 44px;
      background: rgba(0,0,0,0.7);
      border: 1px solid rgba(255,255,255,0.15);
      border-radius: 50%;
      color: white;
      font-size: 1.2rem;
      cursor: pointer;
      display: flex;
      align-items: center;
      justify-content: center;
      z-index: 10;
      transition: background 0.2s;
    }
    .carousel-btn:hover { background: rgba(229,9,20,0.8); }
    .carousel-btn.prev { left: -22px; }
    .carousel-btn.next { right: -22px; }

    /* Poster color palette for variety */
    .poster-1 { background: linear-gradient(160deg, #2d1b3d, #1a1a2e, #16213e); }
    .poster-2 { background: linear-gradient(160deg, #3d1b1b, #2e1a1a, #3e1621); }
    .poster-3 { background: linear-gradient(160deg, #1b3d2d, #1a2e1a, #163e2e); }
    .poster-4 { background: linear-gradient(160deg, #3d2d1b, #2e2e1a, #3e3616); }
    .poster-5 { background: linear-gradient(160deg, #1b2d3d, #1a1a2e, #16213e); }
    .poster-6 { background: linear-gradient(160deg, #3d1b2d, #2e1a2e, #3e1621); }
    .poster-7 { background: linear-gradient(160deg, #2d3d1b, #1a2e2e, #213e16); }
    .poster-8 { background: linear-gradient(160deg, #1b3d3d, #1a2e3e, #16213e); }
    .poster-9 { background: linear-gradient(160deg, #3d1b1b, #2e1a3e, #3e1636); }
    .poster-10 { background: linear-gradient(160deg, #2d1b3d, #3e1a1a, #163e3e); }

    /* ===== FEATURES ===== */
    .features {
      padding: 50px 0;
    }
    .features-grid {
      display: grid;
      grid-template-columns: repeat(4, 1fr);
      gap: 16px;
    }
    .feature-card {
      background: linear-gradient(145deg, #1a1a2e, #16162a);
      border-radius: 12px;
      padding: 28px 24px;
      display: flex;
      flex-direction: column;
      justify-content: space-between;
      min-height: 240px;
      transition: transform 0.2s, background 0.2s;
    }
    .feature-card:hover {
      transform: translateY(-4px);
      background: linear-gradient(145deg, #20203a, #1c1c32);
    }
    .feature-title {
      font-size: 1.3rem;
      font-weight: 700;
      margin-bottom: 12px;
      line-height: 1.25;
    }
    .feature-desc {
      font-size: 0.95rem;
      color: var(--text-muted);
      line-height: 1.5;
    }
    .feature-icon {
      align-self: flex-end;
      margin-top: 20px;
      width: 48px;
      height: 48px;
      display: flex;
      align-items: center;
      justify-content: center;
      font-size: 1.6rem;
      opacity: 0.7;
    }

    /* ===== FAQ ===== */
    .faq {
      padding: 50px 0;
    }
    .faq-list {
      max-width: 800px;
      margin: 0 auto;
    }
    .faq-item {
      margin-bottom: 6px;
    }
    .faq-question {
      width: 100%;
      display: flex;
      justify-content: space-between;
      align-items: center;
      padding: 20px 24px;
      background: #1a1a1a;
      border: none;
      color: var(--text);
      font-size: 1.1rem;
      font-weight: 400;
      cursor: pointer;
      text-align: left;
      transition: background 0.2s;
    }
    .faq-question:hover { background: #252525; }
    .faq-question .icon {
      font-size: 1.5rem;
      transition: transform 0.3s ease;
      flex-shrink: 0;
      margin-left: 16px;
    }
    .faq-item.active .faq-question .icon {
      transform: rotate(45deg);
    }
    .faq-answer {
      max-height: 0;
      overflow: hidden;
      transition: max-height 0.35s ease, padding 0.35s ease;
      background: #1a1a1a;
    }
    .faq-item.active .faq-answer {
      max-height: 400px;
    }
    .faq-answer-inner {
      padding: 20px 24px;
      font-size: 1rem;
      color: var(--text-muted);
      line-height: 1.6;
      border-top: 1px solid #2a2a2a;
    }

    /* ===== BOTTOM CTA ===== */
    .cta-section {
      padding: 60px 0 50px;
      text-align: center;
    }
    .cta-section .cta-prompt {
      font-size: clamp(1rem, 1.8vw, 1.2rem);
      color: var(--text-muted);
      margin-bottom: 24px;
    }

    /* ===== FOOTER ===== */
    .footer {
      padding: 50px 0 40px;
      border-top: 1px solid #222;
    }
    .footer .section-container {
      max-width: 900px;
    }
    .footer-contact {
      font-size: 0.95rem;
      color: var(--text-muted);
      margin-bottom: 28px;
    }
    .footer-contact a { color: var(--text-muted); text-decoration: underline; }
    .footer-links {
      display: grid;
      grid-template-columns: repeat(4, 1fr);
      gap: 14px;
      margin-bottom: 28px;
    }
    .footer-links a {
      font-size: 0.85rem;
      color: var(--text-muted);
    }
    .footer-links a:hover { text-decoration: underline; }
    .footer-lang {
      margin-bottom: 20px;
    }
    .footer-lang select {
      background: transparent;
      color: var(--text-muted);
      border: 1px solid var(--border);
      padding: 8px 14px;
      border-radius: 4px;
      font-size: 0.85rem;
      cursor: pointer;
    }
    .footer-lang select option { background: #222; }
    .footer-legal {
      font-size: 0.78rem;
      color: #555;
      line-height: 1.6;
    }

    /* ===== RESPONSIVE ===== */
    @media (max-width: 1024px) {
      .features-grid {
        grid-template-columns: repeat(2, 1fr);
      }
    }
    @media (max-width: 768px) {
      .header { padding: 16px 20px; }
      .section-container { padding: 0 20px; }
      .hero { min-height: 75vh; padding: 100px 20px 50px; }
      .email-form {
        flex-direction: column;
        align-items: stretch;
      }
      .btn-cta {
        justify-content: center;
        padding: 14px 24px;
      }
      .carousel-card { width: 150px; }
      .card-poster { height: 210px; }
      .card-rank { font-size: 6rem; }
      .carousel-btn { display: none; }
      .features-grid {
        grid-template-columns: 1fr;
        gap: 12px;
      }
      .feature-card { min-height: auto; padding: 24px 20px; }
      .footer-links {
        grid-template-columns: repeat(2, 1fr);
      }
    }
    @media (max-width: 480px) {
      .logo { font-size: 1.3rem; }
      .hero h1 { font-size: 1.75rem; }
      .hero-subtitle { font-size: 1rem; }
      .faq-question { font-size: 0.95rem; padding: 16px 18px; }
      .carousel-card { width: 130px; }
      .card-poster { height: 180px; }
      .card-rank { font-size: 5rem; }
    }
  </style>
</head>
<body>

  <!-- HEADER -->
  <header class="header">
    <div class="logo">StreamWave</div>
    <div class="header-right">
      <select class="lang-select" aria-label="Language">
        <option>English</option>
      </select>
      <a href="login.html" class="btn-signin">Sign In</a>
    </div>
  </header>

  <!-- HERO -->
  <section class="hero">
    <div class="hero-bg"></div>
    <div class="hero-content">
      <h1>Unlimited films, series and more</h1>
      <p class="hero-subtitle">Starts at $15.98. Cancel at any time.</p>
      <p class="hero-prompt">Ready to watch? Enter your email to create or restart your membership.</p>
      <form class="email-form" onsubmit="return false;">
        <input type="email" placeholder="Email address" aria-label="Email address" required>
        <button type="submit" class="btn-cta">Get Started <span class="arrow">&rsaquo;</span></button>
      </form>
    </div>
  </section>

  <!-- TRENDING -->
  <section class="trending">
    <div class="section-container">
      <h2 class="section-title">Trending now</h2>
      <div class="carousel-wrapper">
        <button class="carousel-btn prev" aria-label="Previous" onclick="scrollCarousel(-1)">&#8249;</button>
        <div class="carousel-track" id="carouselTrack">
          <div class="carousel-card">
            <div class="card-poster poster-1">
              <span class="card-rank">1</span>
              <span class="card-title">Bloodhounds</span>
            </div>
          </div>
          <div class="carousel-card">
            <div class="card-poster poster-2">
              <span class="card-rank">2</span>
              <span class="card-title">BEEF</span>
            </div>
          </div>
          <div class="carousel-card">
            <div class="card-poster poster-3">
              <span class="card-rank">3</span>
              <span class="card-title">XO, Kitty</span>
            </div>
          </div>
          <div class="carousel-card">
            <div class="card-poster poster-4">
              <span class="card-rank">4</span>
              <span class="card-title">War Machine</span>
            </div>
          </div>
          <div class="carousel-card">
            <div class="card-poster poster-5">
              <span class="card-rank">5</span>
              <span class="card-title">Bridgerton</span>
            </div>
          </div>
          <div class="carousel-card">
            <div class="card-poster poster-6">
              <span class="card-rank">6</span>
              <span class="card-title">Stranger Things</span>
            </div>
          </div>
          <div class="carousel-card">
            <div class="card-poster poster-7">
              <span class="card-rank">7</span>
              <span class="card-title">Agent from Above</span>
            </div>
          </div>
          <div class="carousel-card">
            <div class="card-poster poster-8">
              <span class="card-rank">8</span>
              <span class="card-title">Boyfriend on Demand</span>
            </div>
          </div>
          <div class="carousel-card">
            <div class="card-poster poster-9">
              <span class="card-rank">9</span>
              <span class="card-title">KPop Demon Hunters</span>
            </div>
          </div>
          <div class="carousel-card">
            <div class="card-poster poster-10">
              <span class="card-rank">10</span>
              <span class="card-title">Emily in Paris</span>
            </div>
          </div>
        </div>
        <button class="carousel-btn next" aria-label="Next" onclick="scrollCarousel(1)">&#8250;</button>
      </div>
    </div>
  </section>

  <!-- FEATURES -->
  <section class="features">
    <div class="section-container">
      <h2 class="section-title">More reasons to join</h2>
      <div class="features-grid">
        <div class="feature-card">
          <div>
            <div class="feature-title">Enjoy on your TV</div>
            <div class="feature-desc">Watch on smart TVs, PlayStation, Xbox, Chromecast, Apple TV, Blu-ray players and more.</div>
          </div>
          <div class="feature-icon" aria-hidden="true">&#128250;</div>
        </div>
        <div class="feature-card">
          <div>
            <div class="feature-title">Download your series to watch offline</div>
            <div class="feature-desc">Save your favourites easily and always have something to watch.</div>
          </div>
          <div class="feature-icon" aria-hidden="true">&#11015;&#65039;</div>
        </div>
        <div class="feature-card">
          <div>
            <div class="feature-title">Watch everywhere</div>
            <div class="feature-desc">Stream unlimited films and series on your phone, tablet, laptop and TV.</div>
          </div>
          <div class="feature-icon" aria-hidden="true">&#127760;</div>
        </div>
        <div class="feature-card">
          <div>
            <div class="feature-title">Create profiles for children</div>
            <div class="feature-desc">Send children on adventures with their favourite characters in a space made just for them — free with your membership.</div>
          </div>
          <div class="feature-icon" aria-hidden="true">&#128118;</div>
        </div>
      </div>
    </div>
  </section>

  <!-- FAQ -->
  <section class="faq">
    <div class="section-container">
      <h2 class="section-title">Frequently Asked Questions</h2>
      <div class="faq-list">
        <div class="faq-item">
          <button class="faq-question" aria-expanded="false">
            What is StreamWave?
            <span class="icon">+</span>
          </button>
          <div class="faq-answer">
            <div class="faq-answer-inner">StreamWave is a streaming service that offers a wide variety of award-winning TV programmes, films, anime, documentaries and more — on thousands of internet-connected devices. You can watch as much as you want, whenever you want, without a single advert — all for one low monthly price. There's always something new to discover, and new TV programmes and films are added every week!</div>
          </div>
        </div>
        <div class="faq-item">
          <button class="faq-question" aria-expanded="false">
            How much does StreamWave cost?
            <span class="icon">+</span>
          </button>
          <div class="faq-answer">
            <div class="faq-answer-inner">Watch StreamWave on your smartphone, tablet, smart TV, laptop or streaming device, all for one fixed monthly fee. Plans range from $15.98 to $29.98/month.</div>
          </div>
        </div>
        <div class="faq-item">
          <button class="faq-question" aria-expanded="false">
            Where can I watch?
            <span class="icon">+</span>
          </button>
          <div class="faq-answer">
            <div class="faq-answer-inner">Watch anywhere, anytime. Sign in with your StreamWave account to watch instantly on the web from your personal computer or on any internet-connected device that offers the StreamWave app, including smart TVs, smartphones, tablets, streaming media players and game consoles. You can also download your favourite programmes with the iOS or Android app. Use downloads to watch while you're on the go and without an internet connection. Take StreamWave with you anywhere.</div>
          </div>
        </div>
        <div class="faq-item">
          <button class="faq-question" aria-expanded="false">
            How do I cancel?
            <span class="icon">+</span>
          </button>
          <div class="faq-answer">
            <div class="faq-answer-inner">StreamWave is flexible. You can easily cancel your account online in two clicks. There are no cancellation fees — start or stop your account at any time.</div>
          </div>
        </div>
        <div class="faq-item">
          <button class="faq-question" aria-expanded="false">
            What can I watch on StreamWave?
            <span class="icon">+</span>
          </button>
          <div class="faq-answer">
            <div class="faq-answer-inner">StreamWave has an extensive library of feature films, documentaries, series, anime, award-winning StreamWave originals, and more. Watch as much as you want, any time you want.</div>
          </div>
        </div>
        <div class="faq-item">
          <button class="faq-question" aria-expanded="false">
            Is StreamWave good for children?
            <span class="icon">+</span>
          </button>
          <div class="faq-answer">
            <div class="faq-answer-inner">The StreamWave Children's experience is included in your membership to give parents control while children enjoy family-friendly TV programmes and films in their own space. Children's profiles come with PIN-protected parental controls that let you restrict the maturity rating of content children can watch and block specific titles you don't want children to see.</div>
          </div>
        </div>
      </div>
    </div>
  </section>

  <!-- BOTTOM CTA -->
  <section class="cta-section">
    <div class="section-container">
      <p class="cta-prompt">Ready to watch? Enter your email to create or restart your membership.</p>
      <form class="email-form" onsubmit="return false;">
        <input type="email" placeholder="Email address" aria-label="Email address" required>
        <button type="submit" class="btn-cta">Get Started <span class="arrow">&rsaquo;</span></button>
      </form>
    </div>
  </section>

  <!-- FOOTER -->
  <footer class="footer">
    <div class="section-container">
      <p class="footer-contact">Questions? <a href="#">Contact us</a>.</p>
      <div class="footer-links">
        <a href="#">FAQ</a>
        <a href="#">Help Centre</a>
        <a href="#">Account</a>
        <a href="#">Media Centre</a>
        <a href="#">Investor Relations</a>
        <a href="#">Jobs</a>
        <a href="#">Ways to Watch</a>
        <a href="#">Terms of Use</a>
        <a href="#">Privacy</a>
        <a href="#">Cookie Preferences</a>
